      {
        "step": 3,
        "label": "SVD Dekompozitsiyasi",
        "detail": "Matritsani U, Sigma va V^T ga ajratish"
      },
      {
        "step": 4,
        "label": "Asosiy Komponentlar",
        "detail": "Eng katta eigenqiymatlar bo'yicha ma'lumotni siqish"
      }
